package com.tianmu.agent.feedback;

import com.tianmu.agent.core.FeedbackAnalysis.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Text is always escaped. Report markup is trusted code, never generated by the model. */
public final class FeedbackReportRenderer {
    public record Detail(Topic topic,int depth,List<String> examples){}
    private FeedbackReportRenderer(){}
    private static String e(Object value){return Objects.toString(value,"").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    public static byte[] render(Asset asset,List<Topic> topics){
        var s=new StringBuilder("<!doctype html><html lang=\"zh-CN\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>观众反馈报告</title><style>body{margin:0;background:#f3f6f8;color:#193042;font:16px/1.7 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:30px}header,section{padding:26px;border-radius:14px;background:white;margin:18px 0}header{background:#163e52;color:white}h1,h2{line-height:1.4}small,footer{color:#627580}header small{color:#d3e6ee}.metrics{display:flex;gap:22px;flex-wrap:wrap}.topic{border-left:4px solid #5ca4b5}p{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:600px){main{padding:12px}header,section{padding:18px}}</style><main>");
        s.append("<header><h1>视频").append(asset.request().query().videoId()).append(" · 观众反馈报告</h1><p>统计区间：").append(e(asset.request().query().start())).append(" 至 ").append(e(asset.request().query().end())).append("（北京时间，结束时刻不计入）</p><small>所选来源：").append(e(asset.request().sources())).append("；快照时点：").append(e(asset.snapshot().dataAsOf())).append("</small></header>");
        var c=asset.snapshot().counts();s.append("<section><h2>反馈概况</h2><div class=\"metrics\">");
        if(asset.model().equals("demo-scripted-feedback"))s.append("<strong>模拟数据，仅用于工程演示</strong>");
        if(asset.request().sources().contains(Source.COMMENT))s.append("<span>评论及回复 <b>").append(c.comments()).append("</b> · 作者 ").append(c.authorComments()).append("</span>");
        if(asset.request().sources().contains(Source.DANMAKU))s.append("<span>弹幕 <b>").append(c.danmaku()).append("</b> · 作者 ").append(c.authorDanmaku()).append("</span>");
        s.append("<span>可识别观众 ").append(c.uniqueAudience()).append("</span></div><p>本次已按批次完整处理所选来源的 ").append(c.total()).append(" 条保留记录。父评论语境不重复计数。覆盖核对通过不等于所有语义判断都正确。</p></section>");
        if(topics.isEmpty())s.append("<section><h2>本次没有反馈记录</h2><p>仅说明指定来源和统计范围内没有记录，不代表视频其他时间没有互动。</p></section>");
        for(var topic:topics)s.append("<section class=\"topic\"><h2>").append(e(topic.title())).append("</h2><small>覆盖 ").append(topic.messages()).append(" 条，其中作者 ").append(topic.authorMessages()).append(" 条；主题引用 ").append(e(topic.id())).append("</small><p>").append(e(topic.observation())).append("</p>")
                .append(topic.recommendation().isBlank()?"":"<h3>可考虑的行动</h3><p>"+e(topic.recommendation())+"</p>").append("</section>");
        if(asset.video()!=null)s.append("<section><h2>视频依据</h2><p>").append(e(asset.video().summary())).append("</p><small>来源版本 ").append(e(asset.video().sourceVersion())).append("；覆盖 ").append(e(asset.video().coverage())).append("；采样位置 ").append(e(asset.video().sampledAtMs())).append("ms。采样帧不能核实连续动作或音量问题。</small></section>");
        s.append("<footer>原始反馈、局部主题与全部成员关系保存在私有证据中，可由当前授权任务回查。报告突出上层主题，不把未展示的子主题当作不存在。模型：").append(e(asset.model())).append("；分析规则：").append(e(asset.policyHash())).append("</footer></main></html>");
        return s.toString().getBytes(StandardCharsets.UTF_8);
    }
    public static byte[] render(Asset asset,List<Topic> topics,List<Detail> details,Map<String,Long> daily){
        String base=new String(render(asset,topics),StandardCharsets.UTF_8);var extra=new StringBuilder();
        if(!daily.isEmpty()){
            extra.append("<section><h2>互动时间分布</h2><p>按反馈创建时间统计（北京时间），不是视频播放位置。</p><table><tr><th>日期</th><th>记录数</th></tr>");
            daily.forEach((date,count)->extra.append("<tr><td>").append(e(date)).append("</td><td>").append(count).append("</td></tr>"));extra.append("</table></section>");
        }
        if(!details.isEmpty()){
            extra.append("<section><h2>局部话题与原话举例</h2><p>以下按层级展示最多60个局部话题，避免上层归纳掩盖具体意见。子层级的次数已包含在上层，不能相加。例子仅作说明，完整成员可从私有分析证据下钻核对。</p>");
            for(var detail:details){var t=detail.topic();extra.append("<details><summary>").append(e(t.title())).append(" · 层级 ").append(detail.depth()).append(" · ").append(t.messages()).append(" 条（作者 ").append(t.authorMessages()).append("）</summary><p>").append(e(t.observation())).append("</p><p>").append(e(t.recommendation())).append("</p>");
                for(var quote:detail.examples())extra.append("<blockquote>").append(e(quote)).append("</blockquote>");
                extra.append("<small>主题引用：").append(e(t.id())).append("</small></details>");}
            extra.append("</section>");
        }
        return base.replace("<footer>",extra+"<footer>").getBytes(StandardCharsets.UTF_8);
    }
}
